-- Unit 1 gap-fill sentences (every sentence contains the target in the exact form that is its answer).
-- Safe to run more than once: it only inserts or updates gap_fill rows.
begin;
on conflict (context_id) do update set
  vocabulary_id=excluded.vocabulary_id,
  occurrence_id=excluded.occurrence_id,
  sense_id=excluded.sense_id,
  context_type=excluded.context_type,
  prompt_text=excluded.prompt_text,
  target_rewrite=excluded.target_rewrite,
  accepted_answers=excluded.accepted_answers,
  misconception_category=excluded.misconception_category,
  status=excluded.status,
  updated_at=now();
commit;
